`timescale 1ns / 1ps
`default_nettype none
`include "tb_check.svh"

// pll.sv is generated by ecppll; this checks its EHXPLLL configuration through
// the behavioural model in tbs/models/EHXPLLL.v (which also enforces the ECP5
// PFD/VCO/output frequency ranges): 25 MHz in -> 200 MHz clkout0 (serial DDR
// clock) and 40 MHz clkout1 (pixel clock), both 50% duty, every clkout1 rising
// edge coinciding with a clkout0 rising edge, locked.
module tb_pll;
    logic clkin = 1'b0;
    always #20 clkin = ~clkin;   // 25 MHz

    wire clkout0, clkout1, locked;

    pll dut (.clkin(clkin), .clkout0(clkout0), .clkout1(clkout1), .locked(locked));

    int checks = 0;

    // Time and running count of clkout0 rising edges; sampled 0.1 ns after
    // another clock's edge so coincident edges are settled.
    realtime t_rise0 = -1.0;
    int      n_rise0 = 0;
    always @(posedge clkout0) begin
        t_rise0 = $realtime;
        n_rise0++;
    end

    initial begin : main
        realtime t_rise, t_fall, t_prev;
        int      n_prev;

        #1;
        `CHECK(locked === 1'b0, ("locked=%b at power-up", locked))

        // Lock within 1 us (25 reference cycles).
        fork
            wait (locked === 1'b1);
            begin
                #1us;
                $fatal(1, "PLL did not lock within 1 us");
            end
        join_any
        disable fork;
        checks++;

        // clkout0 200 MHz: 5 ns period, 50% duty, 400 consecutive cycles.
        @(posedge clkout0);
        t_prev = $realtime;
        for (int i = 0; i < 400; i++) begin
            @(negedge clkout0);
            t_fall = $realtime;
            @(posedge clkout0);
            t_rise = $realtime;
            `CHECK(t_rise - t_prev == 5.0, ("clkout0 period %0.3f ns, expected 5.000", t_rise - t_prev))
            `CHECK(t_fall - t_prev == 2.5, ("clkout0 high time %0.3f ns, expected 2.500", t_fall - t_prev))
            `CHECK(locked === 1'b1, ("lock lost at %0t", $time))
            t_prev = t_rise;
        end

        // clkout1 40 MHz: 25 ns period, 50% duty, 80 consecutive cycles; every
        // rising edge coincides with a clkout0 rising edge, 5 clkout0 cycles
        // per clkout1 cycle.
        @(posedge clkout1);
        t_prev = $realtime;
        #0.1;
        n_prev = n_rise0;
        for (int i = 0; i < 80; i++) begin
            @(negedge clkout1);
            t_fall = $realtime;
            @(posedge clkout1);
            t_rise = $realtime;
            #0.1;
            `CHECK(t_rise0 == t_rise, ("clkout1 rose at %0.3f ns, last clkout0 rise %0.3f ns", t_rise, t_rise0))
            `CHECK(t_rise - t_prev == 25.0, ("clkout1 period %0.3f ns, expected 25.000", t_rise - t_prev))
            `CHECK(t_fall - t_prev == 12.5, ("clkout1 high time %0.3f ns, expected 12.500", t_fall - t_prev))
            `CHECK(n_rise0 - n_prev == 5, ("%0d clkout0 cycles per clkout1 cycle, expected 5", n_rise0 - n_prev))
            `CHECK(locked === 1'b1, ("lock lost at %0t", $time))
            t_prev = t_rise;
            n_prev = n_rise0;
        end

        // Exactly 8 clkout0 cycles per reference cycle, phase-aligned.
        @(posedge clkin);
        #0.1;
        n_prev = n_rise0;
        for (int i = 0; i < 20; i++) begin
            @(posedge clkin);
            t_rise = $realtime;
            #0.1;
            `CHECK(t_rise0 == t_rise, ("clkout0 not rising with clkin (cycle %0d)", i))
            `CHECK(n_rise0 - n_prev == 8, ("%0d clkout0 cycles per clkin cycle, expected 8", n_rise0 - n_prev))
            n_prev = n_rise0;
        end

        $display("PASS tb_pll: %0d checks", checks);
        $finish;
    end

    initial begin
        #100us;
        $fatal(1, "timeout");
    end

    `DUMP_WAVES(tb_pll)
endmodule

`default_nettype wire
